-- 3. Rename earlier rooms in place, so their requests keep them.
update rooms set name_th = 'ECB1201' where name_th = 'EC1201' and building_id = (select id from buildings where name_th = 'ECB1 คณะเศรษฐศาสตร์ อาคาร 1' order by id limit 1) and not exists (select 1 from rooms x where x.building_id = rooms.building_id and x.name_th = 'ECB1201');
update rooms set name_th = 'ECB1202' where name_th = 'EC1202' and building_id = (select id from buildings where name_th = 'ECB1 คณะเศรษฐศาสตร์ อาคาร 1' order by id limit 1) and not exists (select 1 from rooms x where x.building_id = rooms.building_id and x.name_th = 'ECB1202');
update rooms set name_th = 'ECB1301' where name_th = 'EC1301' and building_id = (select id from buildings where name_th = 'ECB1 คณะเศรษฐศาสตร์ อาคาร 1' order by id limit 1) and not exists (select 1 from rooms x where x.building_id = rooms.building_id and x.name_th = 'ECB1301');
update rooms set name_th = 'ECB2201' where name_th = 'EC2201' and building_id = (select id from buildings where name_th = 'ECB2 คณะเศรษฐศาสตร์ อาคาร 2' order by id limit 1) and not exists (select 1 from rooms x where x.building_id = rooms.building_id and x.name_th = 'ECB2201');
update rooms set name_th = 'ห้องประชุมย่อย (Subaltern Room)' where name_th = 'ห้องประชุมย่อย Subaltern Room (ชั้นใต้ดิน)' and building_id = (select id from buildings where name_th = 'คณะสังคมศาสตร์ อาคารปฏิบัติการ (อาคาร 04107)' order by id limit 1) and not exists (select 1 from rooms x where x.building_id = rooms.building_id and x.name_th = 'ห้องประชุมย่อย (Subaltern Room)');

